"""Design Add and Search Words Data Structure — trie plus wildcard DFS.

A '.' branches into every child, so search recurses; concrete letters follow a
single edge.

Time: O(len(word)) typical, O(26^dots * len) worst case   Space: O(total chars)
"""


class WordDictionary:
    END = "$"

    def __init__(self):
        self._root = {}

    def addWord(self, word: str) -> None:
        node = self._root
        for ch in word:
            node = node.setdefault(ch, {})
        node[self.END] = True

    def search(self, word: str) -> bool:
        def walk(node: dict, i: int) -> bool:
            if i == len(word):
                return self.END in node
            ch = word[i]
            if ch == ".":
                return any(walk(child, i + 1)
                           for key, child in node.items() if key != self.END)
            return ch in node and walk(node[ch], i + 1)

        return walk(self._root, 0)
